INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (19, 'REF-01037', 'catalogue', 12, NULL, 'full', 9, 9, '6e725b0be41f32d13870faf7ec538d19527d83593ecf12d1e7d39ffc48e9fd30', 1, 'full-read', 'Third run of the digest. Before this scan was recorded: the derived full text (nine of nine pages, page-marked) was read in full against every active parameter and lens, and the nine page renders p0000 to p0008 were read in this run; every numbered checklist item (derived from scratchpad/session_2026-11-13-edmonton-checklist-pass/items.json), every printed figure, and the statements and group phrases the second critic found missing carry an observation with its sentence verbatim, and every observation is adjudicated once. The colour class of each item (blue = the source''s Code (required), magenta = its Best Practice) is the text-layer colour in items.json, checked against the renders in this run.', '2026-11-13 22:58', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 22:58', 'session_2026-11-13-edmonton-checklist-pass');
